225:                     let r = self.unary()?;
226:                     l = Expr::Bin { op: BinOp::Div, l: Box::new(l), r: Box::new(r) };
227:                 }
228:                 Some(Tok::Op('%')) => {
229:                     self.bump();
230:                     let r = self.unary()?;
231:                     l = Expr::Bin { op: BinOp::Mod, l: Box::new(l), r: Box::new(r) };
232:                 }
233:                 _ => return Ok(l),
234:             }
235:         }
236:     }
237: 
238:     fn unary(&mut self) -> Result<Expr, Error> {
239:         match self.peek() {
240:             Some(Tok::Op('+')) => {
241:                 self.bump();
242:                 self.unary()
243:             }
244:             Some(Tok::Op('-')) => {
245:                 self.bump();
246:                 let e = self.unary()?;
247:                 Ok(Expr::Neg(Box::new(e)))
248:             }
249:             _ => self.power(),
250:         }
251:     }
252: 
253:     fn power(&mut self) -> Result<Expr, Error> {
254:         let base = self.primary()?;
255:         if matches!(self.peek(), Some(Tok::Op('^'))) {
256:             self.bump();
257:             let e = self.unary()?;
258:             Ok(Expr::Bin { op: BinOp::Pow, l: Box::new(base), r: Box::new(e) })
259:         } else {
260:             Ok(base)
261:         }
262:     }
263: 
264:     fn primary(&mut self) -> Result<Expr, Error> {
265:         match self.peek() {
266:             Some(Tok::Num(v)) => {
267:                 let v = *v;
268:                 self.bump();
269:                 Ok(Expr::Num(v))
270:             }
271:             Some(Tok::Ident(name)) => {
272:                 let name = name.clone();
273:                 self.bump();
274:                 if matches!(self.peek(), Some(Tok::Op('('))) {
275:                     self.bump();
276:                     let args = self.args()?;
277:                     Ok(Expr::Call { name, args })
278:                 } else {
279:                     Ok(Expr::Var(name))
280:                 }
281:             }
282:             Some(Tok::Op('(')) => {
283:                 self.bump();
284:                 let e = self.additive()?;
285:                 match self.peek() {
286:                     Some(Tok::Op(')')) => {
287:                         self.bump();
288:                         Ok(e)
289:                     }
290:                     None => Err(Error::UnexpectedEnd),
291:                     Some(_) => Err(Error::UnexpectedToken(self.peek_pos())),
292:                 }
293:             }
294:             None => Err(Error::UnexpectedEnd),
295:             Some(_) => Err(Error::UnexpectedToken(self.peek_pos())),
296:         }
297:     }
298: 
299:     fn args(&mut self) -> Result<Vec<Expr>, Error> {
300:         let mut out = Vec::new();
301:         if matches!(self.peek(), Some(Tok::Op(')'))) {
302:             self.bump();
303:             return Ok(out);
304:         }
305:         loop {
306:             out.push(self.additive()?);
307:             match self.peek() {
308:                 Some(Tok::Op(',')) => self.bump(),
309:                 Some(Tok::Op(')')) => {
310:                     self.bump();
311:                     return Ok(out);
312:                 }
313:                 None => return Err(Error::UnexpectedEnd),
314:                 Some(_) => return Err(Error::UnexpectedToken(self.peek_pos())),
315:             }
316:         }
317:     }
318: }
319: 
320: // ---------------------------------------------------------------------------
321: // Evaluation
322: // ---------------------------------------------------------------------------
323: 
324: pub fn eval(src: &str, vars: &HashMap<String, f64>) -> Result<f64, Error> {
325:     let toks = tokenize(src)?;
326:     let mut p = Parser::new(toks);
327:     let ast = p.parse_expr()?;
328:     if !p.at_end() {
329:         return Err(Error::UnexpectedToken(p.peek_pos()));
330:     }
331:     eval_ast(&ast, vars)
332: }
333: 
334: fn eval_ast(e: &Expr, vars: &HashMap<String, f64>) -> Result<f64, Error> {
335:     match e {
336:         Expr::Num(v) => Ok(*v),
337:         Expr::Var(name) => vars
338:             .get(name)
339:             .copied()
340:             .ok_or_else(|| Error::UnknownVariable(name.clone())),
341:         Expr::Call { name, args } => {
342:             if !matches!(name.as_str(), "abs" | "sqrt" | "min" | "max") {
343:                 return Err(Error::UnknownFunction(name.clone()));
344:             }
345:             match name.as_str() {
346:                 "abs" | "sqrt" => {
347:                     if args.len() != 1 {
348:                         return Err(Error::Arity(name.clone(), args.len()));
349:                     }
350:                 }
351:                 "min" | "max" => {
352:                     if args.is_empty() {
353:                         return Err(Error::Arity(name.clone(), 0));
354:                     }
355:                 }
356:                 _ => unreachable!(),
357:             }
358:             let mut vals = Vec::with_capacity(args.len());
359:             for a in args {
360:                 vals.push(eval_ast(a, vars)?);
361:             }
362:             match name.as_str() {
363:                 "abs" => Ok(vals[0].abs()),
364:                 "sqrt" => Ok(vals[0].sqrt()),
365:                 "min" => Ok(vals.iter().copied().fold(f64::INFINITY, f64::min)),
366:                 "max" => Ok(vals.iter().copied().fold(f64::NEG_INFINITY, f64::max)),
367:                 _ => unreachable!(),
368:             }
369:         }
370:         Expr::Neg(inner) => {
371:             let v = eval_ast(inner, vars)?;
372:             Ok(-v)
373:         }
374:         Expr::Bin { op, l, r } => {
375:             let lv = eval_ast(l, vars)?;
376:             let rv = eval_ast(r, vars)?;
377:             match op {
378:                 BinOp::Add => Ok(lv + rv),
379:                 BinOp::Sub => Ok(lv - rv),
380:                 BinOp::Mul => Ok(lv * rv),
381:                 BinOp::Div => {
382:                     if rv == 0.0 {
383:                         Err(Error::DivisionByZero)
384:                     } else {
385:                         Ok(lv / rv)
386:                     }
387:                 }
388:                 BinOp::Mod => {
389:                     if rv == 0.0 {
390:                         Err(Error::DivisionByZero)
391:                     } else {
392:                         Ok(lv % rv)
393:                     }
394:                 }
395:                 BinOp::Pow => Ok(lv.powf(rv)),
396:             }
397:         }
398:     }
399: }

